expected_functions AS (SELECT f->>'signature' signature,f meta FROM baseline CROSS JOIN LATERAL jsonb_array_elements(data->'functions') f),
expected_tables AS (SELECT t->>'schema'||'.'||(t->>'name') name,t meta FROM baseline CROSS JOIN LATERAL jsonb_array_elements(data->'tables') t),
live_tables AS (SELECT jsonb_build_object('schema',n.nspname,'name',r.relname,'kind',r.relkind,'owner',pg_get_userbyid(r.relowner),'rls',r.relrowsecurity,'force_rls',r.relforcerowsecurity,'acl',r.relacl::text,
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'nullable',NOT a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl::text) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('name',x.conname,'type',x.contype,'definition',pg_get_constraintdef(x.oid),'validated',x.convalidated) ORDER BY x.conname) FROM pg_constraint x WHERE x.conrelid=r.oid),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('definition',pg_get_indexdef(x.indexrelid),'valid',x.indisvalid) ORDER BY pg_get_indexdef(x.indexrelid) COLLATE "C") FROM pg_index x WHERE x.indrelid=r.oid),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid),'function',t.tgfoid::regprocedure::text) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid=r.oid AND NOT t.tgisinternal),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.policyname) FROM pg_policies p WHERE p.schemaname=n.nspname AND p.tablename=r.relname),
 'view_definition',CASE WHEN r.relkind IN('v','m') THEN pg_get_viewdef(r.oid,true) END) meta
 FROM pg_class r JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname IN('public','storage','folha_privado','primeline_quadro_rollout','primeline_pacote2_gate','primeline_documentos_rh_privado') AND r.relkind IN('r','p','v','m')),
function_drift AS (SELECT jsonb_build_object('item',coalesce(e.signature,p.oid::regprocedure::text),'reason','FUNCTION_BASELINE_DRIFT') blocker FROM expected_functions e FULL JOIN (SELECT p.* FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('public','storage','folha_privado','primeline_documentos_rh_privado') AND p.prokind IN('f','p')) p ON p.oid=to_regprocedure(e.signature)
 WHERE p.oid IS NULL OR e.signature IS NULL OR e.meta IS DISTINCT FROM jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'acl',coalesce(p.proacl,acldefault('f',p.proowner))::text,'definition_sha256',encode(sha256(convert_to(replace(pg_get_functiondef(p.oid),chr(13),''),'UTF8')),'hex'))),
