expected_counts(name,expected) AS (VALUES ('quadro_pessoal_alocacao',227::bigint),('quadro_pessoal_movimentos',100::bigint),('ausencias',579::bigint),('ponto_pessoal_obra',0::bigint),('horas_extraordinarias',0::bigint)),
