CASE WHEN NOT EXISTS(SELECT 1 FROM table_drift WHERE blocker->>'item' IN('public.documentos','public.colaboradores','public.viaturas')) THEN ((xpath('/table/row/value/text()',query_to_xml('SELECT count(*) value FROM public.documentos d WHERE d.entidade_tipo IN(''colaborador'',''viatura'') AND NOT(EXISTS(SELECT 1 FROM public.colaboradores c WHERE d.entidade_tipo=''colaborador'' AND c.id=d.entidade_id AND c.empresa_id=d.empresa_id) OR EXISTS(SELECT 1 FROM public.viaturas v WHERE d.entidade_tipo=''viatura'' AND v.id=d.entidade_id AND v.empresa_id=d.empresa_id))',false,false,'')))[1]::text)::bigint END document_mismatches,
CASE WHEN NOT EXISTS(SELECT 1 FROM table_drift WHERE blocker->>'item' IN('public.documentos')) THEN ((xpath('/table/row/value/text()',query_to_xml('SELECT count(*) value FROM public.documentos WHERE entidade_tipo=''empresa'' AND entidade_id IS DISTINCT FROM empresa_id',false,false,'')))[1]::text)::bigint END company_document_mismatches,
CASE WHEN NOT EXISTS(SELECT 1 FROM table_drift WHERE blocker->>'item' IN('public.ausencias_anexos','public.ausencias','public.colaboradores')) THEN ((xpath('/table/row/value/text()',query_to_xml('SELECT count(*) value FROM public.ausencias_anexos an LEFT JOIN public.ausencias a ON a.id=an.ausencia_id LEFT JOIN public.colaboradores c ON c.id=a.colaborador_id WHERE c.id IS NULL',false,false,'')))[1]::text)::bigint END attachment_orphans,
CASE WHEN NOT EXISTS(SELECT 1 FROM table_drift WHERE blocker->>'item' IN('public.orcamento_fases','public.fases')) THEN ((xpath('/table/row/value/text()',query_to_xml('SELECT count(*) value FROM public.orcamento_fases o LEFT JOIN public.fases f ON f.id=o.fase_id WHERE f.id IS NULL OR o.obra_id IS DISTINCT FROM f.obra_id',false,false,'')))[1]::text)::bigint END budget_phase_mismatches),
private_exposed AS (SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN('primeline_encarregado_20261004','primeline_quadro_rollout') AND (c.relowner<>'postgres'::regrole OR EXISTS(SELECT 1 FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE a.grantee<>'postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_attribute x CROSS JOIN LATERAL aclexplode(x.attacl) a WHERE x.attrelid=c.oid AND a.grantee<>'postgres'::regrole))),
